<?php
session_start();require_once '../shared/config.php';
require_once '../shared/security.php';
o2oCsrfToken();requireLogin('vendor','login.php');$vendorId=$_SESSION['vendor_id'];$storeName=$_SESSION['vendor_name'];$db=getDB();
if($_SERVER['REQUEST_METHOD']==='POST'){ o2oRequireCsrf(); }
if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['toggle_id'])){$id=intval($_POST['toggle_id']);$db->prepare("UPDATE items SET available=NOT available WHERE id=? AND vendor_id=?")->execute([$id,$vendorId]);header('Location: inventory.php');exit;}
if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['delete_id'])){$id=intval($_POST['delete_id']);$check=$db->prepare("SELECT COUNT(*) FROM orders WHERE item_id=? AND status IN ('new','in_progress')");$check->execute([$id]);if((int)$check->fetchColumn()>0){header('Location: inventory.php?error=active_orders');exit;}$db->prepare("DELETE FROM items WHERE id=? AND vendor_id=?")->execute([$id,$vendorId]);header('Location: inventory.php');exit;}
$st=$db->prepare("SELECT i.*,(SELECT COUNT(*) FROM orders o WHERE o.item_id=i.id) order_count FROM items i WHERE i.vendor_id=? ORDER BY i.created_at DESC");$st->execute([$vendorId]);$items=$st->fetchAll();
?><!doctype html><html><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Inventory – Vasanam</title><style>
body{font-family:Arial,sans-serif;background:#F4F7F4;margin:0;color:#1A2E1A}.nav{background:#0F1B2D;color:#C9A84C;padding:18px 28px;display:flex;justify-content:space-between}.nav a{color:#E8CC82;text-decoration:none;margin-left:15px}.main{padding:30px;max-width:1100px;margin:auto}.top{display:flex;justify-content:space-between;align-items:center}.btn{background:#0D4F4F;color:#fff;padding:10px 16px;text-decoration:none}.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(260px,1fr));gap:20px}.card{background:#fff;box-shadow:0 2px 10px #0001}.img{height:180px;background:#E8E0D0;display:flex;align-items:center;justify-content:center;font-size:50px;position:relative}.img img{width:100%;height:180px;object-fit:cover}.badge{position:absolute;right:10px;top:10px;padding:5px 9px;border-radius:15px;font-size:11px;background:#D1FAE5;color:#065F46}.off{background:#FEE2E2;color:#991B1B}.body{padding:16px}.name{font:20px Georgia,serif}.cat{color:#C9A84C;font-size:11px;text-transform:uppercase;margin:5px 0}.chips{display:flex;gap:6px;flex-wrap:wrap;margin:10px 0}.chip{background:#FEF9EE;border:1px solid #E8CC82;padding:4px 8px;font-size:11px}.actions{display:flex;gap:7px}.actions form{flex:1}.actions button{width:100%;padding:9px;border:1px solid #ddd;background:#fff}.delete{color:#DC2626!important}.empty{text-align:center;padding:70px;color:#888}</style></head><body><div class="nav"><div>Vasanam · <?=htmlspecialchars($storeName)?></div><div><a href="dashboard.php">Orders</a><a href="add_item.php">Add Item</a><a href="logout.php">Logout</a></div></div><div class="main"><div class="top"><h1>My Inventory (<?=count($items)?>)</h1><a class="btn" href="add_item.php">+ Add Item</a></div><?php if($items):?><div class="grid"><?php foreach($items as $item):?><div class="card"><div class="img"><?php if($item['image_path']&&file_exists('../uploads/items/'.$item['image_path'])):?><img src="../uploads/items/<?=htmlspecialchars($item['image_path'])?>"><?php else:?>👘<?php endif;?><span class="badge <?=$item['available']?'':'off'?>"><?=$item['available']?'✓ Available':'✗ Unavailable'?></span></div><div class="body"><div class="name"><?=htmlspecialchars($item['name'])?></div><div class="cat"><?=htmlspecialchars($item['category']?:'Uncategorized')?></div><div class="chips"><span class="chip">₹<?=number_format($item['rent_per_day'],0)?>/day</span><span class="chip">₹<?=number_format($item['late_charge_per_day'],0)?> late/day</span><span class="chip">📋 <?=$item['order_count']?> orders</span></div><div class="actions"><form method="POST">
<input type="hidden" name="csrf_token" value="<?= htmlspecialchars($_SESSION['csrf_token']) ?>"><input type="hidden" name="toggle_id" value="<?=$item['id']?>"><button><?=$item['available']?'Disable':'Enable'?></button></form><form method="POST" onsubmit="return confirm('Delete this item?')">
<input type="hidden" name="csrf_token" value="<?= htmlspecialchars($_SESSION['csrf_token']) ?>"><input type="hidden" name="delete_id" value="<?=$item['id']?>"><button class="delete">Delete</button></form></div></div></div><?php endforeach;?></div><?php else:?><div class="empty">👘<h2>No items yet</h2><p>Add your first rental item.</p></div><?php endif;?></div></body></html>